// Plain HTML alert. The raw payload comes from the PAYLOAD: marker that the main workflow's Code nodes put in their errors.
// GENERATED by automation/scripts/build-n8n-workflow.mjs. Edit the repo sources, not this node.

const ESCAPES = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;", "`": "&#96;" };

function escapeHtml(value) {
  if (value === null || value === undefined) return "";
  return String(value).replace(/[&<>"'`]/g, (c) => ESCAPES[c]);
}

// ---- node logic ----
const d = $('Error Trigger').first().json;
const cfg = $('Config').first().json;
const ex = d.execution ?? {};
const wf = d.workflow ?? {};
const err = ex.error ?? {};
let message = String(err.message ?? 'Unknown error');
let payload = null;
const at = message.indexOf('\n\nPAYLOAD:');
if (at >= 0) {
  payload = message.slice(at + 10);
  message = message.slice(0, at);
}
const failingNode = err.node?.name ?? ex.lastNodeExecuted ?? 'unknown';
const url = ex.url ?? '';
const id = ex.id ?? String(Date.now());
const pre = 'font-family:Menlo,Consolas,monospace;font-size:12px;line-height:18px;white-space:pre-wrap;word-break:break-word;background:#f6f4ef;border:1px solid #e2e3dd;border-radius:6px;padding:12px;margin:0;';
const row = (k, v) => '<tr><td style="padding:6px 12px 6px 0;color:#566170;font-size:13px;vertical-align:top;white-space:nowrap;">' + escapeHtml(k) + '</td><td style="padding:6px 0;font-size:14px;color:#121726;">' + v + '</td></tr>';
const html = '<!DOCTYPE html><html><body style="margin:0;padding:24px;background:#ffffff;font-family:Inter,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#121726;">'
  + '<h1 style="margin:0 0 4px 0;font-size:20px;">&#9888; Website inquiry workflow failed</h1>'
  + '<p style="margin:0 0 16px 0;color:#566170;font-size:14px;">' + (payload ? 'The inquiry is attached below. Make sure it reaches HubSpot and the person gets a reply.' : 'No inquiry payload was attached. Open the execution to see the input data.') + '</p>'
  + '<table role="presentation" cellpadding="0" cellspacing="0" border="0">'
  + row('Workflow', escapeHtml(wf.name ?? ''))
  + row('Failing node', '<strong>' + escapeHtml(failingNode) + '</strong>')
  + row('Error', escapeHtml(message))
  + row('Execution', url ? '<a href="' + escapeHtml(url) + '" style="color:#4f5f6e;">' + escapeHtml(url) + '</a>' : escapeHtml(id))
  + row('Mode', escapeHtml(ex.mode ?? ''))
  + '</table>'
  + '<h2 style="margin:20px 0 8px 0;font-size:15px;">Raw inquiry payload</h2>'
  + '<pre style="' + pre + '">' + escapeHtml(payload ?? '(not attached)') + '</pre>'
  + '</body></html>';
const text = [
  'Website inquiry workflow failed',
  '',
  'Workflow: ' + (wf.name ?? ''),
  'Failing node: ' + failingNode,
  'Error: ' + message,
  'Execution: ' + (url || id),
  '',
  'Raw inquiry payload:',
  payload ?? '(not attached)',
].join('\n');
const to = String(cfg.SUPPORT_NOTIFY_TO).split(',').map((s) => s.trim()).filter(Boolean);
return [{ json: {
  idempotencyKey: 'inquiry-error/' + id,
  body: {
    from: cfg.MAIL_FROM_NOTIFY,
    to,
    subject: ('⚠ Inquiry workflow failed: ' + failingNode).slice(0, 200),
    html,
    text,
    tags: [{ name: 'type', value: 'inquiry_error' }],
  },
} }];

// Same retry policy as the main workflow: 429/5xx/network only, never a 4xx.
// GENERATED by automation/scripts/build-n8n-workflow.mjs. Edit the repo sources, not this node.

const MAX_RETRIES = 3;

/**
 * Decides what to do with a Resend response (HTTP node in full-response,
 * never-error mode, with "continue on error" for network failures).
 * Retries only 429 / 5xx / network errors, up to MAX_RETRIES times with
 * backoff of 2s, 4s, 8s. A 4xx is never retried.
 */
function classifySend(resp, attempt) {
  const status = resp?.statusCode;
  if (typeof status === "number" && status >= 200 && status < 300) {
    return { action: "sent", status, id: resp.body?.id ?? null, attempt };
  }
  const retryable = status === undefined || status === 429 || status >= 500;
  const detail = String(resp?.body?.message ?? resp?.error?.message ?? resp?.statusMessage ?? "no response").slice(0, 500);
  if (retryable && attempt < MAX_RETRIES) {
    return { action: "retry", status: status ?? "network", waitSeconds: 2 ** (attempt + 1), attempt, detail };
  }
  return { action: "failed", status: status ?? "network", attempt, detail };
}

// ---- node logic ----
const r = classifySend($input.first().json, $runIndex);
if (r.action === 'failed') throw new Error(`Inquiry error alert could not be sent (${r.status}): ${r.detail}`);
return [{ json: r }];
